// Code generation shared by scripts/generate.mjs and scripts/check-generated.mjs.
// Input: openapi.json. Output: the exact text of every generated file, so the
// check can compare without writing anything.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

export const ROOT = fileURLToPath(new URL("..", import.meta.url));
export const SPEC_PATH = `${ROOT}openapi.json`;
export const SCHEMA_PATH = `${ROOT}src/generated/schema.ts`;
export const OPERATIONS_PATH = `${ROOT}src/generated/operations.ts`;
export const README_PATH = `${ROOT}README.md`;
export const README_START = "<!-- methods:start (generated by npm run generate; do not edit) -->";
export const README_END = "<!-- methods:end -->";

const HEADER = "// This file is generated from openapi.json by scripts/generate.mjs.\n// Do not edit it by hand. Run `npm run generate` after updating the spec.\n";
const HTTP_METHODS = ["get", "post", "put", "patch", "delete"];

/**
 * Facts the spec does not state, confirmed against the gateway source.
 * Each entry is a spec gap to close upstream; remove it once the spec says it.
 */
const OVERRIDES = {
  // The spec describes a flat body. Live, the body is { result: {...} }.
  get_me: { wrapped: true },
  // The spec has no response schema. Live, the body is { result: <operation> }.
  get_operation: {
    wrapped: true,
    resultType: "Operation",
    resultImport: 'import type { Operation } from "../operation.js";',
    // Finished list-mode operations page their rows with ?cursor=.
    extraQuery: "{ cursor?: string | number }",
  },
  // The spec has no response schema. Live, the body is { result: {...} }.
  pause_campaign: { wrapped: true, resultType: "Record<string, unknown>" },
  // OpenAI-shaped chat completion. Never unwrapped.
  llm: { responseKind: "flat" },
};

/** Request body fields the SDK refuses, with the reason shown to the caller. */
const UNSUPPORTED_BODY_FIELDS = {
  llm: { stream: "Streaming is not supported by this SDK version. Call llm() without stream." },
};

export function loadSpec() {
  return JSON.parse(readFileSync(SPEC_PATH, "utf8"));
}

const camel = (id) => id.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());
const pascal = (id) => {
  const c = camel(id);
  return c[0].toUpperCase() + c.slice(1);
};

function oneLine(text) {
  if (!text) return "";
  const first = text.split(/\n\s*\n/)[0].replace(/\s+/g, " ").trim();
  const sentence = first.match(/^(.+?[.!?])(\s|$)/);
  return (sentence ? sentence[1] : first).trim();
}

function jsonSchema(content) {
  return content?.["application/json"]?.schema;
}

function envelopeInfo(schema) {
  if (!schema) return null;
  const branches = schema.anyOf ?? schema.oneOf ?? [schema];
  if (!branches.every((b) => b?.properties && "result" in b.properties)) return null;
  const withMeta = branches.filter((b) => "layrcake" in b.properties && (b.required ?? []).includes("layrcake")).length;
  return { meta: withMeta === branches.length ? "always" : withMeta === 0 ? "never" : "sometimes" };
}

/** Every error code the spec declares, checked for consistency across operations. */
/** True when the 200 result has a `dry_run: true` plan branch and the request takes dry_run. */
function hasDryRun(okSchema, bodySchema) {
  if (!bodySchema?.properties?.dry_run || !okSchema) return false;
  const envelopes = okSchema.anyOf ?? okSchema.oneOf ?? [okSchema];
  return envelopes.some((env) => {
    const result = env?.properties?.result;
    const branches = result?.anyOf ?? result?.oneOf ?? [];
    return branches.some((b) => b?.properties?.dry_run?.const === true);
  });
}

function errorCodes(spec, problems) {
  const seen = new Map();
  const visit = (node, where) => {
    if (!node || typeof node !== "object") return;
    const codes = node.properties?.error?.properties?.code?.enum;
    if (Array.isArray(codes)) seen.set(JSON.stringify(codes), [...(seen.get(JSON.stringify(codes)) ?? []), where]);
    for (const value of Object.values(node)) visit(value, where);
  };
  for (const [path, item] of Object.entries(spec.paths)) {
    for (const method of HTTP_METHODS) if (item[method]) visit(item[method].responses, `${method.toUpperCase()} ${path}`);
  }
  if (seen.size === 0) throw new Error("openapi.json declares no error codes");
  if (seen.size > 1) problems.push(`error code enums differ across operations (${seen.size} variants); using their union`);
  return [...new Set([...seen.keys()].flatMap((k) => JSON.parse(k)))];
}

export function describeOperations(spec) {
  const fallback = JSON.parse(readFileSync(`${ROOT}scripts/fallback-summaries.json`, "utf8"));
  const problems = [];
  const ops = [];
  for (const [path, item] of Object.entries(spec.paths)) {
    for (const method of HTTP_METHODS) {
      const op = item[method];
      if (!op) continue;
      if (!op.operationId) throw new Error(`${method.toUpperCase()} ${path} has no operationId`);
      const id = op.operationId;
      const override = OVERRIDES[id] ?? {};
      const params = [...(item.parameters ?? []), ...(op.parameters ?? [])];
      const pathParams = params.filter((p) => p.in === "path").map((p) => p.name);
      const templated = [...path.matchAll(/\{([^}]+)\}/g)].map((m) => m[1]);
      if (templated.join() !== pathParams.join()) throw new Error(`${id}: path template and path parameters disagree`);
      const query = params.filter((p) => p.in === "query");
      const idem = params.find((p) => p.in === "header" && p.name.toLowerCase() === "idempotency-key");
      const bodySchema = jsonSchema(op.requestBody?.content);
      const bodyProps = Object.keys(bodySchema?.properties ?? {});
      const body = !bodySchema || bodyProps.length === 0 ? "none" : op.requestBody.required && (bodySchema.required ?? []).length > 0 ? "required" : "optional";

      const ok = op.responses?.["200"];
      const okContent = ok?.content ?? {};
      // Runtime: "text" for CSV, "flat" only by override (llm), otherwise "unwrap":
      // a { result, layrcake? } body is unwrapped whatever the spec says.
      // Types: an envelope schema yields its result; a flat schema is the result itself.
      let responseKind = "unwrap";
      let shape = "flat";
      let meta = "never";
      if (okContent["text/csv"] || (Object.keys(okContent).length > 0 && !okContent["application/json"])) {
        responseKind = "text";
      } else {
        const env = envelopeInfo(jsonSchema(okContent));
        if (env) {
          shape = "envelope";
          meta = env.meta;
        }
      }
      if (override.responseKind) responseKind = override.responseKind;
      if (override.wrapped && shape === "envelope") throw new Error(`${id}: the spec now describes the envelope; drop the wrapped override`);
      if (override.wrapped) problems.push(`${id}: ${ok?.content ? "the spec describes a flat body" : "the spec has no 200 body schema"}, but the API returns { result } (SDK override in use)`);
      if (!ok?.content && !override.wrapped) problems.push(`${id}: 200 response has no schema`);
      const accepted = op.responses?.["202"] && jsonSchema(op.responses["202"].content) ? true : false;

      let summary = oneLine(op.summary) || oneLine(op.description);
      let summarySource = "spec";
      if (!summary) {
        summary = fallback[id] ?? "";
        summarySource = "fallback";
        if (!summary) throw new Error(`${id}: no summary in the spec or scripts/fallback-summaries.json`);
      }
      ops.push({
        id,
        method: method.toUpperCase(),
        path,
        name: camel(id),
        type: pascal(id),
        summary,
        summarySource,
        pathParams,
        query: query.length > 0 || override.extraQuery ? "optional" : "none",
        queryRequired: query.some((p) => p.required),
        hasSpecQuery: query.length > 0,
        extraQuery: override.extraQuery,
        idempotency: idem ? (idem.required ? "required" : "optional") : "none",
        body,
        bodyRequestOptional: !op.requestBody?.required,
        responseKind,
        shape,
        meta,
        accepted,
        resultType: override.resultType,
        resultImport: override.resultImport,
        unsupported: UNSUPPORTED_BODY_FIELDS[id],
        dryRun: shape === "envelope" && hasDryRun(jsonSchema(okContent), bodySchema),
      });
    }
  }
  const names = new Set();
  for (const op of ops) {
    if (names.has(op.name)) throw new Error(`duplicate method name ${op.name}`);
    names.add(op.name);
  }
  const missing = ops.filter((o) => o.summarySource === "fallback").map((o) => o.id);
  if (missing.length) problems.push(`${missing.length} operations have no summary or description: ${missing.join(", ")}`);
  return { ops, problems, errorCodes: errorCodes(spec, problems) };
}

function q(s) {
  return JSON.stringify(s);
}

function emitOperations({ ops, errorCodes }) {
  const L = [];
  L.push(HEADER);
  L.push('import type { operations } from "./schema.js";');
  L.push('import type { LayrcakeResponse, OperationSpec, RequestInput, RequestOptions } from "../core.js";');
  for (const imp of new Set(ops.map((o) => o.resultImport).filter(Boolean))) L.push(imp);
  L.push("");
  L.push("/** Every error code the API declares. The server may add codes; treat unknown ones as their HTTP status. */");
  L.push(`export const API_ERROR_CODES = [\n${errorCodes.map((c) => `  ${q(c)},`).join("\n")}\n] as const;`);
  L.push("export type ApiErrorCode = (typeof API_ERROR_CODES)[number];");
  L.push("");
  L.push("/** Wire facts for every operation, derived from the spec. */");
  L.push("export const OPERATIONS = {");
  for (const o of ops) {
    const fields = [
      `id: ${q(o.id)}`,
      `method: ${q(o.method)}`,
      `path: ${q(o.path)}`,
      `idempotency: ${q(o.idempotency)}`,
      `response: ${q(o.responseKind)}`,
    ];
    if (o.unsupported) fields.push(`unsupported: ${JSON.stringify(o.unsupported)}`);
    L.push(`  ${o.name}: { ${fields.join(", ")} },`);
  }
  L.push("} as const satisfies Record<string, OperationSpec>;");
  L.push("");

  for (const o of ops) {
    const T = `operations[${q(o.id)}]`;
    L.push(`// ${o.method} ${o.path}`);
    if (o.body !== "none") {
      const raw = `${o.bodyRequestOptional ? `NonNullable<${T}["requestBody"]>` : `${T}["requestBody"]`}["content"]["application/json"]`;
      if (o.unsupported) {
        const keys = Object.keys(o.unsupported).map(q).join(" | ");
        // The refused fields are boolean switches: only false (or absent) is accepted.
        L.push(`export type ${o.type}Params = Omit<${raw}, ${keys}> & { [K in ${keys}]?: false };`);
      } else L.push(`export type ${o.type}Params = ${raw};`);
    }
    if (o.query !== "none") {
      const parts = [];
      if (o.hasSpecQuery) parts.push(`NonNullable<${T}["parameters"]["query"]>`);
      if (o.extraQuery) parts.push(o.extraQuery);
      L.push(`export type ${o.type}Query = ${parts.join(" & ")};`);
    }
    const body200 = `${T}["responses"][200]["content"]["application/json"]`;
    let result;
    if (o.resultType) result = o.resultType;
    else if (o.responseKind === "text") result = "string";
    else if (o.shape === "envelope") result = `${body200}["result"]`;
    else result = body200;
    if (o.accepted) result = `${result} | ${T}["responses"][202]["content"]["application/json"]`;
    if (o.dryRun) {
      L.push(`type ${o.type}Any = ${result};`);
      L.push(`/** What ${o.name} returns when it runs. */`);
      L.push(`export type ${o.type}Result = Exclude<${o.type}Any, { dry_run: true }>;`);
      L.push(`/** What ${o.name} returns with \`dry_run: true\`: the plan, nothing run or charged. */`);
      L.push(`export type ${o.type}Plan = Extract<${o.type}Any, { dry_run: true }>;`);
    } else L.push(`export type ${o.type}Result = ${result};`);
    let meta = "null";
    if (o.shape === "envelope" && o.meta === "always") meta = `${body200}["layrcake"]`;
    if (o.shape === "envelope" && o.meta === "sometimes") meta = `Extract<${body200}, { layrcake: unknown }>["layrcake"] | null`;
    L.push(`export type ${o.type}Response = LayrcakeResponse<${o.type}Result, ${meta}>;`);
    if (o.dryRun) L.push(`export type ${o.type}PlanResponse = LayrcakeResponse<${o.type}Plan, ${meta}>;`);
    L.push("");
  }

  const metaTypes = ops.filter((o) => o.shape === "envelope" && o.meta !== "never").map((o) => `NonNullable<${o.type}Response["layrcake"]>`);
  L.push("/** The `layrcake` block on a metered response: request_id, credits_charged, credits_available and routing facts. */");
  L.push(`export type LayrcakeMeta =\n${metaTypes.map((t) => `  | ${t}`).join("\n")};`);
  L.push("");

  L.push("/** One typed method per operation in the spec. The Layrcake client extends this class. */");
  L.push("export abstract class LayrcakeMethods {");
  L.push("  /** @internal */");
  L.push("  protected abstract _request<T>(operation: OperationSpec, input: RequestInput, options?: RequestOptions): Promise<T>;");
  for (const o of ops) {
    const args = [];
    const input = [];
    for (const p of o.pathParams) {
      args.push(`${camel(p)}: string`);
      input.push(p === camel(p) ? p : `${p}: ${camel(p)}`);
    }
    const pathInput = o.pathParams.length ? `path: { ${input.join(", ")} }` : null;
    const inputs = [pathInput].filter(Boolean);
    const before = args.length;
    if (o.body !== "none") {
      args.push(o.body === "required" ? `params: ${o.type}Params` : `params: ${o.type}Params = {}`);
      inputs.push("body: params");
    }
    if (o.query !== "none") {
      args.push(o.queryRequired ? `query: ${o.type}Query` : `query: ${o.type}Query = {}`);
      inputs.push("query");
    }
    args.push("options?: RequestOptions");
    const doc = [`${o.summary}`, "", `\`${o.method} ${o.path}\``];
    if (o.idempotency === "required") doc.push("", "Idempotency key: required. The SDK sends one if you do not. Pass your own to retry safely later.");
    else if (o.idempotency === "optional") doc.push("", "Idempotency key: optional. The SDK sends one so automatic retries are safe.");
    if (o.accepted) doc.push("", "May answer 202 with the approval state instead of a result.");
    if (o.dryRun) doc.push("", "Pass `dry_run: true` to get the plan instead: the most it can cost and any limit it would trip. Nothing runs or is charged.");
    const jsdoc = ["  /**", ...doc.map((line) => (line ? `   * ${line}` : "   *")), "   */"];
    L.push("");
    if (o.dryRun) {
      // Overloads: dry_run: true resolves to the plan, otherwise to the outcome.
      const opt = o.body === "required" ? "" : "?";
      const head = args.slice(0, before);
      const tail = args.slice(before + 1);
      const sig = (params, ret) => `  ${o.name}(${[...head, params, ...tail].join(", ")}): Promise<${ret}>;`;
      L.push(...jsdoc);
      L.push(sig(`params: ${o.type}Params & { dry_run: true }`, `${o.type}PlanResponse`));
      L.push(...jsdoc);
      L.push(sig(`params${opt}: ${o.type}Params & { dry_run?: false }`, `${o.type}Response`));
      L.push(...jsdoc);
      L.push(sig(`params${opt}: ${o.type}Params`, `${o.type}Response | ${o.type}PlanResponse`));
      L.push(`  ${o.name}(${args.join(", ")}): Promise<${o.type}Response | ${o.type}PlanResponse> {`);
      L.push(`    return this._request<${o.type}Response | ${o.type}PlanResponse>(OPERATIONS.${o.name}, { ${inputs.join(", ")} }, options);`);
    } else {
      L.push(...jsdoc);
      L.push(`  ${o.name}(${args.join(", ")}): Promise<${o.type}Response> {`);
      L.push(`    return this._request<${o.type}Response>(OPERATIONS.${o.name}, { ${inputs.join(", ")} }, options);`);
    }
    L.push("  }");
  }
  L.push("}");
  L.push("");
  return L.join("\n");
}

function emitReadmeTable({ ops }) {
  const rows = ops.map((o) => {
    const args = [...o.pathParams.map(camel), ...(o.body !== "none" ? ["params"] : []), ...(o.query !== "none" ? ["query"] : [])];
    return `| \`${o.name}(${args.join(", ")})\` | \`${o.method} ${o.path}\` | ${o.summary.replace(/\|/g, "\\|")} |`;
  });
  return [README_START, "", "| Method | Endpoint | What it does |", "| --- | --- | --- |", ...rows, "", README_END].join("\n");
}

export function spliceReadme(readme, table) {
  const start = readme.indexOf(README_START);
  const end = readme.indexOf(README_END);
  if (start === -1 || end === -1 || end < start) throw new Error("README.md is missing the methods markers");
  return readme.slice(0, start) + table + readme.slice(end + README_END.length);
}

export async function generateAll(spec, readme) {
  const ast = await openapiTS(spec, { defaultNonNullable: false, silent: true });
  const schema = HEADER + "\n" + astToString(ast);
  const described = describeOperations(spec);
  return {
    files: {
      [SCHEMA_PATH]: schema,
      [OPERATIONS_PATH]: emitOperations(described),
      [README_PATH]: spliceReadme(readme, emitReadmeTable(described)),
    },
    problems: described.problems,
    operations: described.ops,
  };
}
